.process-box {
    display: none; 
}

/* 2. 唯独当它是“正在生成的内容”（即最后一个子元素）时：显示为加载条 */
.process-box:last-child {
    display: block; /* 激活显示 */

    /* 下面是加载条的样式 */
    height: 40px;
    background: #f0f2f5;
    border: 1px dashed #ccc;
    border-radius: 4px;
    margin: 10px 0;
    position: relative;
    overflow: hidden;

    /* 关键：强制隐藏容器内部实际生成的文字 */
    font-size: 0 !important;
    color: transparent !important;
}

/* 3. 加载条上的文字和动画（通过伪元素实现） */
.process-box:last-child::before {
    content: "⏳ 魔法构筑中... (完成后自动折叠)";

    /* 文字样式 */
    font-size: 14px;
    color: #555;
    font-weight: bold;
    font-family: sans-serif;

    /* 居中定位 */
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1;
}

/* 4. 扫光动画效果 */
.process-box:last-child::after {
    content: "";
    position: absolute;
    top: 0; left: -100%;
    width: 100%; height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.8), transparent);
    animation: loading-scan 1.5s infinite;
}

@keyframes loading-scan {
    0% { left: -100%; }
    100% { left: 100%; }
}

:root {
  /* 边框色：青色能量流 */
  --scifi-border: #00f3ff; 
  /* 背景色：半透明深空黑，带一点蓝调 */
  --scifi-bg: rgba(5, 20, 35, 0.95);
  /* 标题文字色：高亮全息白 */
