/* --- Global Code Block Styles: Classical Parchment --- */
.markdown-body pre {
  background-color: #fdf6e3 !important; /* Parchment paper background */
  border: 1px solid #d3c0a5;
  border-radius: 4px;
  box-shadow: 2px 2px 8px rgba(133, 101, 62, 0.15);
  margin-top: 1em !important;
  margin-bottom: 1em !important;
  overflow: hidden;
}

/* --- Header Bar: Old Paper Header --- */
.markdown-body pre > div > div.flex.justify-between {
  background: #f5e5c5; /* Slightly darker parchment */
  border-bottom: 1px solid #d3c0a5 !important;
  padding-left: 16px !important;
  height: 40px !important;
}

/* --- Language Label: Serif & Sepia --- */
.markdown-body pre > div > div.flex.justify-between > div:first-child {
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 16px !important;
  font-weight: 600;
  color: #654321 !important; /* Dark brown (Sepia) */
  text-shadow: 1px 1px 0px #fff9f0;
  display: flex;
  align-items: center;
}

/* --- Code Content Area: Parchment & Sepia Text --- */
.markdown-body pre > div > div[node] {
  background-color: #fdf6e3 !important; /* Match main parchment background */
  color: #5d5145 !important; /* Softer sepia */
  padding: 16px !important;
  line-height: 1.6;
}
.markdown-body pre code {
  font-family: 'Courier New', Courier, monospace;
  font-size: 14px;
  white-space: pre-wrap !important;
  word-break: break-all;
}

/* --- Copy Button: Match Header (CRITICAL) --- */
.markdown-body pre div[data-tooltip-id^="copy-tooltip"] {
  background-color: #f5e5c5 !important; /* Match header background */
}
.markdown-body pre div[data-tooltip-id^="copy-tooltip"]:hover {
  background-color: #e9d8b8 !important; /* Hover state */
}
.markdown-body pre div[data-tooltip-id^="copy-tooltip"] > div {
  /* The default dark icon works well on a light background, no filter needed */
}
.markdown-body pre div[data-tooltip-id^="copy-tooltip"] > div:hover {
  background-color: #e9d8b8 !important;
}

/* === Specific Block Themes & Icons === */

/* --- [Time] Block: Sunstone Border --- */
.markdown-body pre:has(code.language-Time) { border-color: #fabd2f; }
.markdown-body pre:has(code.language-Time) > div > div.flex > div:first-child::before {
  content: '📜'; margin-right: 8px; font-size: 18px;
}

/* --- [Voice] Block: Inkwell Border --- */
.markdown-body pre:has(code.language-Voice) { border-color: #458588; }
.markdown-body pre:has(code.language-Voice) > div > div.flex > div:first-child::before {
  content: '✒️'; margin-right: 8px; font-size: 18px;
}

/* --- [Status] Block: Heraldry Border --- */
