/* --- Collapsible Details/Summary Styling --- */
.markdown-body details {
  background-color: #fdf6e3; /* Parchment paper background */
  border: 1px solid #d3c0a5;
  border-radius: 4px;
  margin: 1em 0;
  box-shadow: 2px 2px 8px rgba(133, 101, 62, 0.15);
  overflow: hidden; /* Important for child border-radius */
}

.markdown-body summary {
  background-color: #f5e5c5; /* Header background, slightly darker parchment */
  padding: 10px 16px;
  cursor: pointer;
  font-family: Georgia, 'Times New Roman', serif;
  color: #654321; /* Dark brown (Sepia) */
  font-weight: 600;
  font-size: 16px;
  list-style: none; /* Hide default marker */
  outline: none; /* Hide focus ring */
  transition: background-color 0.2s;
  border-bottom: 1px solid transparent; /* Placeholder for open state */
}

.markdown-body summary::-webkit-details-marker {
  display: none; /* Hide default marker in WebKit */
}

.markdown-body summary:hover {
  background-color: #e9d8b8;
}

/* Custom Marker */
.markdown-body summary::before {
  content: '▸';
  color: #8f7a5e;
  margin-right: 8px;
  display: inline-block;
  transition: transform 0.2s ease-in-out;
}

.markdown-body details[open] > summary::before {
  transform: rotate(90deg);
}

.markdown-body details[open] > summary {
  border-bottom: 1px solid #d3c0a5; /* Separator when open */
}

