/* --- 浅色/默认模式 --- */
:root {
    --classical-bg: #f5efdc; /* 羊皮卷背景 */
    --classical-primary: #8c6d52; /* 主古典棕 */
    --classical-secondary: #c8b5a6; /* 次要灰褐色 */
    --classical-text: #5a3a22; /* 深棕文字 */
    --classical-accent: #b48c62; /* 点缀亮棕 */
    --classical-border: #dcd0b9; /* 边框色 */
    --classical-hover-bg: #e9e2ce; /* 悬停背景 */
}

/* --- 黑夜模式变量 --- */
@media (prefers-color-scheme: dark) {
    :root {
        --classical-bg: #2c251e; /* 深胡桃木背景 */
        --classical-primary: #d4af37; /* 黄铜/金色 */
        --classical-secondary: #5a4a3a; /* 暗棕褐色 */
        --classical-text: #e0d6c5; /* 灰白/羊皮纸文字 */
        --classical-accent: #e8c772; /* 亮金色 */
        --classical-border: #4a4032; /* 暗边框 */
        --classical-hover-bg: #3c342b; /* 悬停深色背景 */
    }
}

/* =========================================
   🗺️ 阿兹加尔大陆地图专属 CSS 美化 (小白特制版)
   ========================================= */

/* 地图折叠面板整体样式 */
.fantasy-map-panel {
    background: linear-gradient(145deg, #1a1a1a, #2a2a2a);
    border: 1px solid #c5a059; /* 奇幻暗金色边框 */
    border-radius: 8px;
    margin: 10px 0;
    padding: 5px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.5);
}

/* 标题栏 (Summary) 样式 */
.fantasy-map-panel summary {
    color: #e8d08d; /* 羊皮纸文字颜色 */
    font-weight: bold;
    font-size: 1.1em;
    cursor: pointer;
    padding: 8px 12px;
    list-style: none;
    text-shadow: 1px 1px 2px #000;
    transition: color 0.3s ease;
}

.fantasy-map-panel summary::-webkit-details-marker {
    display: none; /* 隐藏默认的小三角 */
}

.fantasy-map-panel summary:hover {
    color: #fff3c7; /* 鼠标悬浮时发光 */
    text-shadow: 0 0 5px #c5a059;
}

/* 地图容器：实现画框效果和交互动画 */
.map-container {
    position: relative;
    margin: 10px;
    border: 3px double #8b6914; /* 双线复古画框 */
    border-radius: 4px;
    overflow: hidden;
    background-color: #000;
    box-shadow: inset 0 0 20px rgba(0,0,0,0.8);
}

/* 地图图片本身：添加复古滤镜和悬浮放大效果 */
.map-container img {
    width: 100%;
    height: auto;
    display: block;
    /* 增加微弱的暖色调和对比度，营造羊皮纸地图质感 */
    filter: sepia(0.3) contrast(1.1) brightness(0.9);
    transition: transform 0.5s ease, filter 0.5s ease;
}

/* 鼠标悬浮在地图上时的效果 */
.map-container:hover img {
    transform: scale(1.03); /* 轻微放大，方便主人查看细节 */
    filter: sepia(0.1) contrast(1.2) brightness(1); /* 变得更清晰明亮 */
}

/* 地图底部的描述文字 */
.map-caption {
    text-align: center;
    font-size: 0.85em;
    color: #a08c5b;
    font-family: "Georgia", serif;
    margin-bottom: 5px;
    letter-spacing: 1px;
}

/* 地图图片本身：添加复古滤镜、悬浮放大效果和放大镜指针 */
.map-container img {
    width: 100%;
    height: auto;
    display: block;
    filter: sepia(0.3) contrast(1.1) brightness(0.9);
    transition: transform 0.5s ease, filter 0.5s ease;
    cursor: zoom-in; /* 🌟小白新增：鼠标悬浮时变成放大镜图标喵！ */
}
